export default async function next({ items, runId, previous }, ctx) {
  if (!/^[-A-Za-z0-9_]{8,128}$/.test(runId) || !Array.isArray(items))
    throw Error("Invalid run or items");
  const ids = items.map((x) => String(x.Id || ""));
  if (ids.some((x) => !x) || new Set(ids).size !== ids.length)
    throw Error("Workflow IDs must be unique");
  let i = previous?.index ?? 0;
  for (; i < items.length; i++) {
    let item = items[i],
      id = String(item.Id),
      key = "node-update:" + runId + ":" + id;
    if (!Array.isArray(item.outdated_nodes)) throw Error("Missing outdated_nodes");
    let s = await ctx.state.get(key);
    if (s?.status === "done") continue;
    if (s) throw Error("Inspect pending workflow update " + key);
    return { state: { index: i + 1 }, more: true, id, item, key };
  }
  return { state: { index: i }, more: false, id: "unused", item: {}, key: "" };
}

