import { createHmac } from "node:crypto";
export default function sign({ workflow, item, symbol, major, add, secret }) {
  if (!secret) throw Error("Missing relay secret");
  const payload = Buffer.from(
    JSON.stringify({
      workflow,
      outdated: item.outdated_nodes,
      symbol,
      onlyMajorChanges: major,
      addNodesToCanvas: add,
    }),
  ).toString("base64");
  return {
    body: { payload, signature: createHmac("sha256", secret).update(payload).digest("hex") },
  };
}

