export default function result({ status, body, id }) {
  if (
    status !== 200 ||
    body?.id !== id ||
    !Number.isInteger(body.changed) ||
    !body.body ||
    !Array.isArray(body.body.nodes)
  )
    throw Error("Inspect rename relay");
  return { changed: body.changed > 0, body: body.body };
}

