export default async function confirm({ status, key, id, body, runId }, ctx) {
  if (status < 200 || status >= 300) throw Error("Inspect workflow update");
  let name = body.name;
  let k = "node-update:" + runId + ":report",
    r = (await ctx.state.get(k)) || [];
  if (!r.some((x) => x.id === id)) await ctx.state.set(k, [...r, { id, name }]);
  await ctx.state.set(key, { status: "done" });
  return { ok: true };
}

