export default async function report({ runId, base }, ctx) {
  let rows = (await ctx.state.get("node-update:" + runId + ":report")) || [],
    key = "node-update:" + runId + ":mail",
    s = await ctx.state.get(key);
  if (s?.status === "done" || rows.length === 0) return { send: false, body: "", key };
  if (s) throw Error("Inspect pending summary email");
  const esc = (s) =>
    String(s)
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;");
  let body =
    "These workflows contain outdated nodes:<br><ul>" +
    rows
      .map(
        (x) =>
          '<li><a href="' +
          esc(base.replace(/\/$/, "") + "/workflow/" + encodeURIComponent(x.id)) +
          '">' +
          esc(x.name) +
          "</a></li>",
      )
      .join("") +
    "</ul>";
  await ctx.state.set(key, { status: "pending" });
  return { send: true, body, key };
}

